# Independent base-R validation of Phase 2D scenario tables.
args<-commandArgs(trailingOnly=FALSE); file_arg<-grep("^--file=",args,value=TRUE); script_path<-normalizePath(sub("^--file=","",file_arg),winslash="/"); root<-normalizePath(file.path(dirname(script_path),"../../.."),winslash="/")
d<-file.path(root,"data/processed/scenarios"); a<-read.csv(file.path(d,"materials_scenario_assumptions.csv"),stringsAsFactors=FALSE,na.strings=NULL); n<-read.csv(file.path(d,"materials_nodes_scenario.csv"),stringsAsFactors=FALSE,na.strings=NULL); e<-read.csv(file.path(d,"materials_edges_scenario.csv"),stringsAsFactors=FALSE,na.strings=NULL); c<-read.csv(file.path(d,"materials_corridor_evaluation.csv"),stringsAsFactors=FALSE,na.strings=NULL)
bn<-read.csv(file.path(root,"data/processed/networks/materials_system_nodes.csv"),stringsAsFactors=FALSE,na.strings=NULL); be<-read.csv(file.path(root,"data/processed/networks/materials_system_edges.csv"),stringsAsFactors=FALSE,na.strings=NULL)
stopifnot(nrow(bn)==30L,nrow(be)==31L,nrow(a)==30L,nrow(n)==48L,nrow(e)==36L,nrow(c)==6L)
stopifnot(length(unique(paste(a$scenario_id,a$scenario_year)))==6L,all(n$reality_status=="fictional"),all(e$relationship_basis=="scenario_assumption"),all(is.na(n$latitude)|n$latitude==""),all(is.na(n$longitude)|n$longitude==""),all(e$assumption_id %in% a$assumption_id),all(tolower(as.character(c$hard_corridor_geometry))=="false"),all(c$direct_interfacility_route_edges==0L))
png(file.path(root,"outputs/figures/materials_scenarios_R_validation.png"),width=1800,height=1000,res=150); par(mfrow=c(1,2),mar=c(8,4,4,1),bg="#f7f4ec"); barplot(table(n$scenario_id),las=2,col=c("#2a9d8f","#355c7d","#9c4f73"),main="Scenario node states",ylab="Count"); barplot(table(e$scenario_year),col=c("#52796f","#84a98c"),main="Edges by horizon",ylab="Count"); mtext("Independent R validation — PASS · 2026 baseline remains 30/31",outer=TRUE,line=-2,font=2,col="#17324d"); dev.off(); cat("PASS: 30 assumptions; 48 scenario nodes; 36 scenario edges; six states; baseline 30/31.\n")
